        const AIYOU_PRODUCT_NAME = 'AIYOUDSH';
        // Unmodified official favicon, reused from AIYOUcodex's declared brand asset.
        const AIYOU_MOKE_LOGO = 'data:image/png;base64,';
        /** Keep the conversation title and change only the native product suffix.
         * Native session/title updates remain the source of the title text. */
        function installAiyouBranding(ctx, page = document) {
            return ctx.effect(() => {
                const nativeName = 'DeepSeek Harness';
                let lastOwned;
                function paint() {
                    const title = page.title;
                    const next = title === nativeName ? AIYOU_PRODUCT_NAME
                        : title.endsWith(' — ' + nativeName) ? title.slice(0, -nativeName.length) + AIYOU_PRODUCT_NAME : title;
                    if (next !== title) { page.title = next; lastOwned = next; }
                }
                const observer = new page.defaultView.MutationObserver(paint);
                observer.observe(page.head, { childList: true, characterData: true, subtree: true });
                paint();
                return () => {
                    observer.disconnect();
                    if (page.title === lastOwned) page.title = page.title === AIYOU_PRODUCT_NAME ? nativeName
                        : page.title.slice(0, -AIYOU_PRODUCT_NAME.length) + nativeName;
                };
            }, 'AIYOUDSH: product title');
        }
